import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, remaining_qty, seq, active]
    seq_counter = [0]

    def add_resting(id_, side, price, qty, seq):
        book[id_] = [side, price, qty, seq, True]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id_))
        else:
            heapq.heappush(sell_heap, (price, seq, id_))

    def pop_best_sell():
        while sell_heap:
            price, seq, id_ = sell_heap[0]
            entry = book.get(id_)
            if entry is None or not entry[4] or entry[2] <= 0:
                heapq.heappop(sell_heap)
                continue
            return id_, entry
        return None, None

    def pop_best_buy():
        while buy_heap:
            negprice, seq, id_ = buy_heap[0]
            entry = book.get(id_)
            if entry is None or not entry[4] or entry[2] <= 0:
                heapq.heappop(buy_heap)
                continue
            return id_, entry
        return None, None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            id_ = order[1]
            entry = book.get(id_)
            if entry is not None and entry[4] and entry[2] > 0:
                entry[4] = False
            continue

        if typ == 'limit':
            _, id_, side, price, qty = order
        elif typ == 'ioc':
            _, id_, side, price, qty = order
        elif typ == 'market':
            _, id_, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq = seq_counter[0]
        seq_counter[0] += 1

        if side == 'buy':
            while remaining > 0:
                sell_id, entry = pop_best_sell()
                if sell_id is None:
                    break
                sell_price = entry[1]
                if typ != 'market' and price is not None and sell_price > price:
                    break
                trade_qty = min(remaining, entry[2])
                trades.append([id_, sell_id, sell_price, trade_qty])
                remaining -= trade_qty
                entry[2] -= trade_qty
                if entry[2] <= 0:
                    entry[4] = False
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                add_resting(id_, 'buy', price, remaining, seq)
        else:  # sell
            while remaining > 0:
                buy_id, entry = pop_best_buy()
                if buy_id is None:
                    break
                buy_price = entry[1]
                if typ != 'market' and price is not None and buy_price < price:
                    break
                trade_qty = min(remaining, entry[2])
                trades.append([buy_id, id_, buy_price, trade_qty])
                remaining -= trade_qty
                entry[2] -= trade_qty
                if entry[2] <= 0:
                    entry[4] = False
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                add_resting(id_, 'sell', price, remaining, seq)

    return trades

